        INDEX `idx_war_bike` (`bike_id`)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

    $conn->query("CREATE TABLE IF NOT EXISTS `warranty_claims` (
        `id` INT AUTO_INCREMENT PRIMARY KEY,
