            $user = current_user($conn);
            $created_by = $user ? $user['id'] : null;
            if ($destination_id <= 0 || $amount <= 0 || !valid_date($deposit_date) || !in_array($deposit_type, ['cash', 'cheque', 'transfer', 'online', 'other'], true)) {
