            $chq_where[] = "p.payment_date >= '" . mysqli_real_escape_string($conn, $chq_from) . "'";
        if ($chq_to)
            $chq_where[] = "p.payment_date <= '" . mysqli_real_escape_string($conn, $chq_to) . "'";
