            if ($edit_dep) {
                $edl_q = $conn->query("SELECT bike_id, SUM(amount) AS amount FROM deposit_allocations WHERE deposit_id=$edit_dep_id GROUP BY bike_id ORDER BY MIN(id) ASC");
