<script>
document.getElementById('licenseKeyInput').addEventListener('input', function(e) {
    let v = this.value.replace(/[^A-Za-z0-9]/g, '').toUpperCase();
    let formatted = '';
    for (let i = 0; i < v.length && i < 24; i++) {
        if (i > 0 && i % 4 === 0) formatted += '-';
        formatted += v[i];
    }
    this.value = formatted;
});
</script>
